function phoneSound(kind,settings=prefs,preview=false){const tone=kind==='message'?settings.messageTone||'chime':settings.unlockTone||'soft',volume=settings.phoneVolume??.5;if(tone==='none'||volume<=0||ctx.audio().mute||(!preview&&kind==='message'&&(prefs.dnd||prefs.huntFocus)))return;const now=performance.now();if(!preview&&now-lastPhoneSound<250)return;lastPhoneSound=now;try{phoneAudio=phoneAudio||new (window.AudioContext||window.webkitAudioContext)();phoneAudio.resume().catch(()=>{});const tones={chime:[880,1175,1568],digital:[660,990],soft:[523,784],bell:[1047,1397,2093]},notes=tones[tone]||tones.soft;notes.forEach((hz,i)=>{const osc=phoneAudio.createOscillator(),gain=phoneAudio.createGain(),time=phoneAudio.currentTime+i*.085;osc.type=tone==='digital'?'triangle':'sine';osc.frequency.value=hz;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(volume*.12,time+.008);gain.gain.exponentialRampToValueAtTime(.0001,time+.24);osc.connect(gain);gain.connect(phoneAudio.destination);osc.start(time);osc.stop(time+.25)})}catch(error){console.debug('Audio do Pokéfone indisponível',error)}}
